#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package LiquidState@8.0.0 #:package Microsoft.Extensions.Hosting@8.0.0 #:package Microsoft.Extensions.Caching.Distributed@8.0.0 #:package System.Diagnostics.DiagnosticSource@8.0.0 #:property LangVersion=preview #:property TargetFramework=net10.0 #:property Nullable=enable #:property ImplicitUsings=enable  using System.Buffers; using System.Diagnostics.Metrics; using System.Text.Json; using LiquidState; using LiquidState.Awaitable; using LiquidState.Awaitable.Core; using Microsoft.Extensions.Caching.Distributed; using Microsoft.Extensions.DependencyInjection; using Microsoft.Extensions.Hosting; using Microsoft.Extensions.Options; using System.Threading.Channels; using System.Threading.Tasks;  // 状态和触发器枚举定义 public enum WorkflowState { Started, Processing, Completed, Failed } public enum WorkflowTrigger { Begin, Process, Complete, Fail }  // 状态机配置选项 public class WorkflowStateMachineOptions {     public TimeSpan Timeout { get; set; } = TimeSpan.FromSeconds(30);     public int MaxRetryAttempts { get; set; } = 3; }  // 状态机接口 public interface IWorkflowStateMachine : IAsyncDisposable {     WorkflowState CurrentState { get; }     Task<bool> CanHandleTriggerAsync(WorkflowTrigger trigger);     Task FireAsync(WorkflowTrigger trigger, CancellationToken ct = default);     IAsyncEnumerable<WorkflowState> StateChangesAsync(CancellationToken ct = default); }  // 状态机实现 public class WorkflowStateMachine : IWorkflowStateMachine {     private readonly Channel<WorkflowState> _stateChannel;     private readonly IStateMachine<WorkflowState, WorkflowTrigger> _stateMachine;          public WorkflowState CurrentState => _stateMachine.CurrentState;      public WorkflowStateMachine(IOptions<WorkflowStateMachineOptions> options)     {         _stateChannel = Channel.CreateUnbounded<WorkflowState>();                  var config = StateMachineFactory.Create<WorkflowState, WorkflowTrigger>();                  config.In(WorkflowState.Started)             .On(WorkflowTrigger.Begin).TransitionTo(WorkflowState.Processing)             .On(WorkflowTrigger.Fail).TransitionTo(WorkflowState.Failed);                      config.In(WorkflowState.Processing)             .On(WorkflowTrigger.Process).TransitionTo(WorkflowState.Processing)             .On(WorkflowTrigger.Complete).TransitionTo(WorkflowState.Completed)             .On(WorkflowTrigger.Fail).TransitionTo(WorkflowState.Failed);                      _stateMachine = config.Build(WorkflowState.Started);     }          public async Task FireAsync(WorkflowTrigger trigger, CancellationToken ct = default)     {         await _stateMachine.FireAsync(trigger, ct);         await _stateChannel.Writer.WriteAsync(_stateMachine.CurrentState, ct);     }          public IAsyncEnumerable<WorkflowState> StateChangesAsync(CancellationToken ct = default)          => _stateChannel.Reader.ReadAllAsync(ct);          public async ValueTask DisposeAsync() => _stateChannel.Writer.Complete(); }  // DI扩展方法 public static class ServiceCollectionExtensions {     public static IServiceCollection AddWorkflowStateMachine(this IServiceCollection services,          Action<WorkflowStateMachineOptions> configure = null)     {         services.Configure(configure ?? (opts => {}));         services.AddSingleton<IWorkflowStateMachine, WorkflowStateMachine>();         return services;     }          public static IServiceCollection AddDistributedStateMachine(this IServiceCollection services,         Action<RedisOptions> configure = null)     {         services.Configure(configure ?? (opts => {}));         services.AddSingleton<IStateRepository, RedisStateRepository>();         services.AddSingleton(typeof(IStateMachine<,>), typeof(MonitoredStateMachine<,>));         return services;     } }  // Redis配置选项 public class RedisOptions {     public TimeSpan SlidingExpiration { get; set; } = TimeSpan.FromMinutes(30); }  // 分布式状态存储接口 public interface IStateRepository {     Task SaveAsync<TState, TTrigger>(string machineId,          IStateMachine<TState, TTrigger> machine);     Task<IStateMachine<TState, TTrigger>?> LoadAsync<TState, TTrigger>(         string machineId, TState initialState); }  // Redis状态存储实现 public class RedisStateRepository : IStateRepository, IAsyncDisposable {     private readonly IDistributedCache _cache;     private readonly IOptions<RedisOptions> _options;          public RedisStateRepository(IDistributedCache cache,          IOptions<RedisOptions> options)     {         _cache = cache;         _options = options;     }          public async Task SaveAsync<TState, TTrigger>(string machineId,          IStateMachine<TState, TTrigger> machine)     {         var bytes = ArrayPool<byte>.Shared.Rent(1024);         try         {             var writer = new ArrayBufferWriter<byte>(bytes);             await JsonSerializer.SerializeAsync(writer.AsStream(),                  new StateMachineData<TState>(machine.CurrentState));                          await _cache.SetAsync(GetKey(machineId), bytes.AsMemory(0, writer.WrittenCount),                 new DistributedCacheEntryOptions                 {                     SlidingExpiration = _options.Value.SlidingExpiration                 });         }         finally         {             ArrayPool<byte>.Shared.Return(bytes);         }     }          public async Task<IStateMachine<TState, TTrigger>?> LoadAsync<TState, TTrigger>(         string machineId, TState initialState)     {         var bytes = await _cache.GetAsync(GetKey(machineId));         if (bytes == null) return null;                  var data = await JsonSerializer.DeserializeAsync<StateMachineData<TState>>(             new MemoryStream(bytes));                      var config = StateMachineFactory.Create<TState, TTrigger>();         // 配置状态转换规则...                  return config.Build(data?.CurrentState ?? initialState);     }          public ValueTask DisposeAsync() => default; }  // AOT优化状态机工厂 public static class AotStateMachineFactory {     [System.Runtime.CompilerServices.ModuleInitializer]     public static void Initialize()     {         // 预编译常见状态机配置         var config = StateMachineFactory.Create<WorkflowState, WorkflowTrigger>();         config.In(WorkflowState.Started)             .On(WorkflowTrigger.Begin).TransitionTo(WorkflowState.Processing);         // 其他状态转换规则...     } }  // 性能监控装饰器 public class MonitoredStateMachine<TState, TTrigger> : IStateMachine<TState, TTrigger> {     private readonly IStateMachine<TState, TTrigger> _inner;     private readonly Counter<int> _transitionCounter;          public TState CurrentState => _inner.CurrentState;          public MonitoredStateMachine(IStateMachine<TState, TTrigger> inner,          IMeterFactory meterFactory)     {         _inner = inner;         var meter = meterFactory.Create("StateMachine");         _transitionCounter = meter.CreateCounter<int>("state_transitions");     }          public Task FireAsync<TArg>(ParameterizedTrigger<TTrigger, TArg> parameterizedTrigger,          TArg arg, CancellationToken cancellationToken = default)     {         _transitionCounter.Add(1);         return _inner.FireAsync(parameterizedTrigger, arg, cancellationToken);     } }  // 示例用法 public static class Program {     public static async Task Main(string[] args)     {         var host = Host.CreateDefaultBuilder(args)             .ConfigureServices(services =>             {                 services.AddWorkflowStateMachine(options =>                 {                     options.MaxConcurrentTransitions = 5;                     options.EnableDiagnostics = true;                 });                                  services.AddDistributedStateMachine(redisOptions =>                 {                     redisOptions.SlidingExpiration = TimeSpan.FromHours(1);                 });             })             .Build();          var stateMachine = host.Services.GetRequiredService<IWorkflowStateMachine>();                  // 触发状态转换         await stateMachine.FireAsync(WorkflowTrigger.Start);         await stateMachine.FireAsync(WorkflowTrigger.Pause);         await stateMachine.FireAsync(WorkflowTrigger.Resume);         await stateMachine.FireAsync(WorkflowTrigger.Complete);          await host.RunAsync();     } }
